import * as React from "react"
import { Link, PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";

const userData: UserProfile = data;

const RetailPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout 
      data={userData}
      iconAndTextColor="Tofu"
      footerLogoFill="fill-Tofu"
      bgColorPage="Trooper"
      bgImage={images.bgRetail.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <section className={styles.container}>  
            <h1 className={`${styles.title} head-3 uppercase`}>{t("retail.title")}</h1>
        </section>
    </Layout>
  )
}

export default RetailPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16 text-Tofu mb-32",
  section: "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "text-center mt-[70%] relative z-40",
}